import { layoutCase } from "./system-design-case-layout";
import type { ComponentType, Design, DesignNode } from "./system-design";

export type CaseNode = DesignNode & { purpose: string; decision: string };
export type FlowStep = { from: string; to: string; title: string; detail: string; why: string; payload: string; kind: "request" | "response" | "event" | "media" | "failure" };
export type Scenario = { id: string; title: string; summary: string; outcome: string; steps: FlowStep[] };
export type SystemCase = { id: string; name: string; category: string; color: string; description: string; requirements: string[]; scale: { assumption: string; calculation: string; implication: string }[]; nodes: CaseNode[]; scenarios: Scenario[]; tradeoffs: { choice: string; reason: string; cost: string }[]; sources: { title: string; url: string; supports: string }[]; assignment: string };
function node(id: string, type: ComponentType, label: string, column: number, row: number, purpose: string, decision: string): CaseNode { return { id, type, label, x: 30 + column * 240, y: 45 + row * 140, purpose, decision }; }
function step(from: string, to: string, title: string, detail: string, why: string, payload: string, kind: FlowStep["kind"] = "request"): FlowStep { return { from, to, title, detail, why, payload, kind }; }
