export function caseDesign(model: SystemCase): Design {
  const pairs = new Map<string, { from: string; to: string; label: string; kind: FlowStep["kind"] }>();
  for (const scenario of model.scenarios) for (const s of scenario.steps) {
    if (!pairs.has(`${s.from}:${s.to}`)) pairs.set(`${s.from}:${s.to}`, { from: s.from, to: s.to, label: s.title.slice(0, 60), kind: s.kind });
  }
  return { version: 1, title: `${model.name} · educational architecture`, ...layoutCase(model.id, model.nodes.map(({ id, type, label, x, y }) => ({ id, type, label, x, y }))), edges: [...pairs.values()].map((pair, i) => ({ id: `case-edge-${i}`, ...pair })) };
}
